package com.healthcare.jwt;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import lombok.RequiredArgsConstructor;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component @RequiredArgsConstructor
public class JwtRequestFilter extends OncePerRequestFilter { private final JwtUtil jwtUtil; private final CustomUserDetailsService uds;
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException, IOException { String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){ String t=h.substring(7); if(jwtUtil.valid(t)&&SecurityContextHolder.getContext().getAuthentication()==null){ var ud=uds.loadUserByUsername(jwtUtil.username(t)); var auth=new UsernamePasswordAuthenticationToken(ud,null,ud.getAuthorities()); auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req)); SecurityContextHolder.getContext().setAuthentication(auth);} } chain.doFilter(req,res);} }
